		//修补章节链接缺失 
//java.log(a+i)
		if(arr[i-1]){
			name=a.text(),
			url=arr[i-1].attr("href");
//java.log(url);

			link=String(url).replace(/(\d+).html/,(h,d)=>`${Number(d)+1}.html`);
//java.log(link);

			}else if(arr[i+1]){
			name=a.text(),
			url=arr[i+1].attr("href");
			link=String(url).replace(/(\d+).html/,(h,d)=>`${Number(d)-1}.html`);
				}else java.log("缺失章节修补失败！");
		list.push({text:name,href:link});
		}else{//正常章节直接获取
			list.push({text:a.text(),
				href:a.attr("href")});
			}
	});
