sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});

	push("分类", null, 1, 1);
fl=["魔幻玄幻","仙侠修真","都市青春","历史军事","科幻游戏","近代现代","同人耽美","架空历史","重生异能","恐怖推理"];
	  fl.map((title,index)=>{
	  	index++;
	    url= `/fenlei${index}_{{page}}.shtml`;
	if(index +1<= fl.length - fl.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.29);}
	});	
	push("完本",  `/wanben1_{{page}}.shtml`, 1, 1);

	push("榜单", null, 1, 1);
bd = [["总点击","allvisit"],["月点击","monthvisit"],["周点击","weekvisit"],["日点击","dayvisit"],["总推荐","allvote"],["月推荐","monthvote"],["周推荐","weekvote"],["日推荐","dayvote"],["总收藏","goodnum"],["字数","size"],["入库","postdate"],["最近","lastupdate"]];
	  bd.map(([title,uri],index)=>{
	    url= `/${uri}/{{page}}.shtml`;
	if(index+1 <= bd.length - bd.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.29);} 	
    	});
JSON.stringify(sort);
